import base64, json, sys, os
sys.path.insert(0, '/app')
os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'escolta_system.settings')
import django; django.setup()
from cadastros.models import FuncionarioPatrimonial
from datetime import datetime

data = json.loads(base64.b64decode('').decode())
imp = 0; skip = 0
for r in data:
    n = r.get('nome','').strip(); c = r.get('cpf','').strip()
    if not n or not c: skip += 1; continue
    if FuncionarioPatrimonial.objects.filter(cpf=c).exists(): skip += 1; continue
    d = None
    nd = r.get('nasc','').strip()
    if nd:
        for f in ('%Y-%m-%d','%d/%m/%Y'):
            try: d = datetime.strptime(nd, f).date(); break
            except: pass
    FuncionarioPatrimonial.objects.create(empresa='jrs_facilities', nome=n, cpf=c, cargo=r.get('cargo',''), nome_mae=r.get('mae',''), data_nascimento=d, status='ativo')
    imp += 1
print(f"Importados: {imp}, Pulados: {skip}")
